# -*- coding: utf-8 -*-# p8_drill_down.py - Drill-down Vendeurimport streamlit as stimport plotly.graph_objects as gofrom config import C, apply_theme, to_rgba, HEALTH_COLORS, ALERT_COLORSfrom components.kpi_cards import section_title, page_header, mini_badgefrom data.loader import load_health, load_diagnosticsfrom data.processor import get_seller_profile, compute_radar_data# Noms de colonnes avec accents en unicodeCOL_PRIORITE   = "Priorit\u00e9 Alerte"COL_CATEGORIE  = "Cat\u00e9gorie"COL_VOLAT      = "Volatilit\u00e9 6m"COL_NEG_30J    = "% Avis N\u00e9g. 30j"COL_NOTE_SNAP  = "Note Snapshot"COL_NOTE_LIV   = "Note Livraison"COL_NOTE_DESC  = "Note Description"COL_NOTE_COMM  = "Note Communication"COL_MOMENTUM   = "Momentum Sentiment"COL_SENT_6M    = "Sentiment 6m"COL_PENTE      = "Pente Sent. 3m"COL_MEMBRE     = "Membre Depuis"COL_NB_AVIS    = "Nb Avis Total"COL_NOM        = "Nom Vendeur"COL_HS         = "Health Score"COL_ID         = "ID Vendeur"COL_PAYS       = "Pays"def _health_bar(score):    color = (C["green"] if score >= 72             else C["orange"] if score >= 55             else C["red"])    pct = min(100, max(0, score))    return (        "<div style='background:{bg};border-radius:4px;height:14px;"        "width:100%;margin-top:4px;'>"        "<div style='width:{pct:.0f}%;height:14px;background:{color};"        "border-radius:4px;'></div></div>"        "<div style='font-size:11px;color:{color};margin-top:2px;'>"        "{score:.1f} / 100</div>"    ).format(bg=C["card2"], pct=pct, color=color, score=score)def render():    page_header(        "Drill-down Vendeur",        "Profil complet - radar multi-criteres - diagnostic et recommandations",        "🔬"    )    df_health = load_health()    df_diag   = load_diagnostics()    filter_pays = st.session_state.get("filter_pays", "Tous")    df_base = (df_health[df_health[COL_PAYS] == filter_pays]               if filter_pays != "Tous" else df_health)    c1, c2, c3 = st.columns([2, 1, 1])    with c1:        search = st.text_input(            "Rechercher un vendeur", "",            key="dd_search",            placeholder="Ex: WatchBox, Bachmann..."        )    with c2:        prio_filter = st.selectbox(            "Priorite",            ["Toutes", "HIGH", "MEDIUM", "LOW", "OK"],            key="dd_prio"        )    with c3:        pays_list = ["Tous"] + sorted(            df_base[COL_PAYS].dropna().unique().tolist()        )        pays_filter = st.selectbox("Pays", pays_list, key="dd_pays")    df_sel = df_base.copy()    if prio_filter != "Toutes":        df_sel = df_sel[df_sel[COL_PRIORITE] == prio_filter]    if pays_filter != "Tous":        df_sel = df_sel[df_sel[COL_PAYS] == pays_filter]    if search.strip():        mask = (            df_sel[COL_NOM].str.contains(search, case=False, na=False) |            df_sel[COL_ID].astype(str).str.contains(search, na=False)        )        df_sel = df_sel[mask]    if df_sel.empty:        st.warning("Aucun vendeur trouve avec ces criteres.")        return    df_sorted = df_sel.sort_values(COL_HS)    seller_options = df_sorted.apply(        lambda r: "{} - {} (HS: {:.1f} - {})".format(            r[COL_NOM], r[COL_PAYS],            r[COL_HS], r[COL_PRIORITE]        ),        axis=1    ).tolist()    seller_ids = df_sorted[COL_ID].tolist()    selected_label = st.selectbox(        "Vendeur ({} resultat{})".format(            len(df_sel), "s" if len(df_sel) > 1 else ""        ),        seller_options,        key="dd_vendeur"    )    selected_id = seller_ids[seller_options.index(selected_label)]    st.markdown(        "<hr style='border-color:{};margin:12px 0;'>".format(C["border"]),        unsafe_allow_html=True    )    profile = get_seller_profile(df_health, int(selected_id))    radar   = compute_radar_data(df_health, int(selected_id))    if not profile:        st.error("Profil introuvable.")        return    cat  = profile.get(COL_CATEGORIE, "N/A")    prio = profile.get(COL_PRIORITE,  "N/A")    cat_color  = HEALTH_COLORS.get(cat,  C["blue"])    prio_color = ALERT_COLORS.get(prio,  C["blue"])    nom    = profile.get(COL_NOM,    "N/A")    pays   = profile.get(COL_PAYS,   "N/A")    membre = profile.get(COL_MEMBRE, None)    membre = int(membre) if membre else "N/A"    nb_avis = int(profile.get(COL_NB_AVIS, 0))    hs      = profile.get(COL_HS, 0)    st.markdown(        "<div style='background:{card};border-radius:12px;padding:20px 24px;"        "border:1px solid {border};margin-bottom:16px;'>"        "<div style='display:flex;justify-content:space-between;"        "align-items:flex-start;'>"        "<div>"        "<div style='font-size:22px;font-weight:700;color:{text};"        "margin-bottom:6px;'>{nom}</div>"        "<div style='font-size:13px;color:{muted};'>"        "Pays : {pays} | Membre depuis : {membre} | {nb_avis:,} avis total"        "</div>"        "</div>"        "<div>{badge_cat} &nbsp; {badge_prio}</div>"        "</div>"        "<div style='margin-top:14px;'>"        "<div style='font-size:12px;color:{muted};margin-bottom:2px;'>"        "Health Score</div>"        "{hbar}"        "</div>"        "</div>".format(            card=C["card"], border=C["border"],            text=C["text"], muted=C["muted"],            nom=nom, pays=pays, membre=membre, nb_avis=nb_avis,            badge_cat=mini_badge(cat, cat_color),            badge_prio=mini_badge("Alerte " + prio, prio_color),            hbar=_health_bar(hs)        ),        unsafe_allow_html=True    )    col_m, col_r = st.columns([1, 1.4])    with col_m:        section_title("Metriques cles")        note_snap = profile.get(COL_NOTE_SNAP, 0) or 0        note_liv  = profile.get(COL_NOTE_LIV,  0) or 0        note_desc = profile.get(COL_NOTE_DESC,  0) or 0        note_comm = profile.get(COL_NOTE_COMM,  0) or 0        momentum  = profile.get(COL_MOMENTUM,   0) or 0        sent_6m   = profile.get(COL_SENT_6M,    0) or 0        pct_neg   = profile.get(COL_NEG_30J,    0) or 0        vol_6m    = profile.get(COL_VOLAT,       0) or 0        pente     = profile.get(COL_PENTE,       0) or 0        metrics = [            ("Note snapshot",    "{:.2f}/5".format(note_snap),     C["green"]),            ("Note livraison",   "{:.2f}/5".format(note_liv),      C["blue"]),            ("Note description", "{:.2f}/5".format(note_desc),     C["blue"]),            ("Note comm.",       "{:.2f}/5".format(note_comm),     C["blue"]),            ("", None, None),            ("Momentum 30j-12m", "{:+.3f}".format(momentum),      C["teal"]),            ("Sentiment 6m",     "{:.3f}".format(sent_6m),        C["teal"]),            ("Avis neg. 30j",    "{:.1f}%".format(pct_neg * 100), C["orange"]),            ("Volatilite 6m",    "{:.3f}".format(vol_6m),         C["orange"]),            ("Pente sent. 3m",   "{:+.4f}".format(pente),         C["purple"]),        ]        for label, val, color in metrics:            if not label:                st.markdown(                    "<hr style='border-color:{};margin:8px 0'>".format(C["grid"]),                    unsafe_allow_html=True                )                continue            st.markdown(                "<div style='display:flex;justify-content:space-between;"                "padding:6px 0;border-bottom:1px solid {grid};'>"                "<span style='font-size:12px;color:{muted};'>{label}</span>"                "<span style='font-size:13px;font-weight:600;"                "color:{color};'>{val}</span>"                "</div>".format(                    grid=C["grid"], muted=C["muted"],                    label=label, color=color, val=val                ),                unsafe_allow_html=True            )    with col_r:        section_title("Profil multi-criteres vs marche")        if radar:            axes = radar["axes"]            v_v  = list(radar["vendor"].values())            v_m  = list(radar["market"].values())            fig_r = go.Figure()            fig_r.add_trace(go.Scatterpolar(                r=v_m + [v_m[0]],                theta=axes + [axes[0]],                name="Mediane marche",                fill="toself",                line=dict(color=C["border"], width=1.5, dash="dot"),                fillcolor=to_rgba(C["border"], 0.13),                hovertemplate="%{theta}<br><b>%{r:.2f}</b><extra></extra>",            ))            fig_r.add_trace(go.Scatterpolar(                r=v_v + [v_v[0]],                theta=axes + [axes[0]],                name=nom,                fill="toself",                line=dict(color=cat_color, width=2.5),                fillcolor=to_rgba(cat_color, 0.2),                hovertemplate="%{theta}<br><b>%{r:.2f}</b><extra></extra>",            ))            apply_theme(fig_r, "")            fig_r.update_layout(                polar=dict(                    bgcolor=C["card"],                    radialaxis=dict(                        visible=True, range=[0, 1],                        showticklabels=False,                        gridcolor=C["grid"], gridwidth=0.5                    ),                    angularaxis=dict(                        gridcolor=C["border"],                        tickfont=dict(color=C["muted"], size=11)                    )                ),                height=360,                legend=dict(                    orientation="h", x=0.5,                    xanchor="center", y=-0.08                )            )            st.plotly_chart(fig_r, use_container_width=True)    nom_vendeur = profile.get(COL_NOM, "")    diag_row = df_diag[df_diag["Vendeur"] == nom_vendeur]    if not diag_row.empty:        section_title("Diagnostic et recommandation", "📋")        d = diag_row.iloc[0]        cause    = str(d.get("Cause Principale", "N/A"))        action   = str(d.get("Action Recommand\u00e9e", "N/A"))        tendance = str(d.get("Tendance 3m", "N/A"))        col_d1, col_d2 = st.columns(2)        with col_d1:            st.markdown(                "<div style='background:{card2};border-left:3px solid {red};"                "border-radius:8px;padding:14px;margin-bottom:8px;'>"                "<div style='font-size:12px;color:{muted};margin-bottom:6px;'>"                "CAUSE PRINCIPALE</div>"                "<div style='font-size:13px;color:{text};font-weight:600;'>"                "{cause}</div>"                "<div style='font-size:12px;color:{muted};margin-top:8px;'>"                "Tendance 3m : "                "<span style='color:{orange};'>{tendance}</span>"                "</div></div>".format(                    card2=C["card2"], red=C["red"], muted=C["muted"],                    text=C["text"], orange=C["orange"],                    cause=cause, tendance=tendance                ),                unsafe_allow_html=True            )        with col_d2:            st.markdown(                "<div style='background:{card2};border-left:3px solid {green};"                "border-radius:8px;padding:14px;margin-bottom:8px;'>"                "<div style='font-size:12px;color:{muted};margin-bottom:6px;'>"                "ACTION RECOMMANDEE</div>"                "<div style='font-size:12px;color:{text};line-height:1.5;'>"                "{action}</div></div>".format(                    card2=C["card2"], green=C["green"],                    muted=C["muted"], text=C["text"],                    action=action                ),                unsafe_allow_html=True            )    else:        st.caption("Pas de diagnostic disponible pour ce vendeur.")